# ordinal -> workout name where the year has more than plain .1 to .5
NAMES = {2015:['15.1','15.1a','15.2','15.3','15.4','15.5'],2018:['18.1','18.2','18.2a','18.3','18.4','18.5'],
         2021:['21.1','21.2','21.3','21.4'],2023:['23.1','23.2A','23.2B','23.3']}
def name(year, o):
    return NAMES[year][o-1] if year in NAMES else '%d.%d' % (year % 100, o)
